import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Verify{public static void main(String[] a)throws Exception{int n=0;try(var paths=Files.walk(Path.of(a[0]))){for(Path p:paths.filter(p->p.toString().endsWith(".class")).toList()){ClassNode c=new ClassNode();new ClassReader(Files.readAllBytes(p)).accept(c,0);for(MethodNode m:c.methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0){new Analyzer<>(new BasicVerifier()).analyze(c.name,m);n++;}}}System.out.println("PASS ASM stack/dataflow: "+n+" methods");}}
